rlong_buffer_cfg=}, but got None\"\n            )\n            assert self.max_resp_len >= self.overlong_buffer_cfg.len, (\n                \"max_resp_len must be larger than overlong_buffer.len\"\n            )\n            assert not self.overlong_buffer_cfg.enable or self.overlong_buffer_cfg.len > 0, (\n                \"overlong_buffer.len must be positive when overlong penalty is enabled,\"\n                f\"but got {self.overlong_buffer_cfg.len}.\"\n                \"To disable the overlong penalty, set overlong_buffer.enable = False\"\n            )\n\n    async def run_single(self, data: DataProto) -> dict:\n        assert len(data) == 1, \"Only support single data item\"\n        data_item = data[0]\n        response_ids = data_item.batch[\"responses\"]\n        response_length = response_ids.shape[-1]\n        valid_response_length = data_item.batch[\"attention_mask\"][-response_length:].sum()\n        valid_response_ids = response_ids[:valid_response_length]\n\n        data_source = data_item.non_tensor_batch[\"data_source\"]\n        ground_truth = data_item.non_tensor_batch[\"reward_model\"][\"ground_truth\"]\n        extra_info = data_item.non_tensor_batch.get(\"extra_info\", {})\n\n        response_str = await self.loop.run_in_executor(\n            None, lambda: self.tokenizer.decode(valid_response_ids, skip_special_tokens=True)\n        )\n        extra_reward_kwargs = (\n            {\n                \"reward_router_address\": self.reward_router_address,\n                \"reward_model_tokenizer\": self.reward_model_tokenizer,\n            }\n            if self.reward_router_address is not None\n            else {}\n        )\n        if self.is_async_reward_score:\n            result = await self.compute_score(\n                data_source=data_source,\n                solution_str=response_str,\n                ground_truth=ground_truth,\n                extra_info=extra_info,\n                **extra_reward_kwargs,\n            )\n        else:\n            result = await self.loop.run_in_executor(\n                None,\n                lambda: self.compute_score(\n                    data_source=data_source,\n…416 tokens truncated…cable law or agreed to in writing, software\n# distributed under the License is distributed on an \"AS IS\" BASIS,\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n# See the License for the specific language governing permissions and\n# limitations under the License.\n\nfrom collections import defaultdict\n\nimport torch\n\nfrom verl import DataProto\nfrom verl.utils.reward_score import default_compute_score\nfrom verl.workers.reward_manager import register\nfrom verl.workers.reward_manager.abstract import AbstractRewardManager\n\n\n@register(\"dapo\")\nclass DAPORewardManager(AbstractRewardManager):\n    \"\"\"The reward manager.\"\"\"\n\n    def __init__(\n        self,\n        tokenizer,\n        num_examine,\n        compute_score=None,\n        reward_fn_key=\"data_source\",\n        max_resp_len=None,\n        overlong_buffer_cfg=None,\n    ) -> None:\n        self.tokenizer = tokenizer\n        self.num_examine = num_examine  # the number of batches of decoded responses to print to the console\n        self.compute_score = compute_score or default_compute_score\n        self.reward_fn_key = reward_fn_key\n        self.overlong_buffer_cfg = overlong_buffer_cfg\n        self.max_resp_len = max_resp_len\n\n        if self.overlong_buffer_cfg is not None:\n            assert self.max_resp_len is not None, (\n                f\"max_resp_len must be provided if {overlong_buffer_cfg=}, but got None\"\n            )\n            assert self.max_resp_len >= self.overlong_buffer_cfg.len, (\n                \"max_resp_len must be larger than overlong_buffer.len\"\n            )\n            assert not self.overlong_buffer_cfg.enable or self.overlong_buffer_cfg.len > 0, (\n                \"overlong_buffer.len must be positive when overlong penalty is enabled,\"\n                f\"but got {self.overlong_buffer_cfg.len}.\"\n                \"To disable the overlong penalty, set overlong_buffer.enable = False\"\n            )\n\n    def __call__(self, data: DataProto, return_dict: bool = False):\n        \"\"\"We will expand this function gradually based on the available datasets\"\"\"\n\n        # If there is rm score, we directly return rm score. Otherwise, we compute via rm_score_fn\n        reward_from_rm_scores = self._extract_reward_from_rm_scores(data, return_dict)\n        if reward_from_rm_scores is not None:\n            return reward_from_rm_scores\n\n        reward_tensor = torch.zeros_like(data.batch[\"responses\"], dtype=torch.float32)\n        reward_extra_info = defaultdict(list)\n\n        already_print_data_sources = {}\n\n        for i in range(len(data)):\n            data_item = data[i]  # DataProtoItem\n\n            prompt_ids = data_item.batch[\"prompts\"]\n\n            prompt_length = prompt_ids.shape[-1]\n\n            valid_prompt_length = data_item.batch[\"attention_mask\"][:prompt_length].sum()\n            valid_prompt_ids = prompt_ids[-valid_prompt_length:]\n\n            response_ids = data_item.batch[\"responses\"]\n            if \"response_mask\" in data_item.batch.keys():\n                valid_response_mask = data_item.batch[\"response_mask\"].to(torch.bool)\n                valid_response_length = valid_response_mask.sum()\n                valid_response_ids = response_ids[valid_response_mask]\n            else:\n                valid_response_length = data_item.batch[\"attention_mask\"][prompt_length:].sum()\n                valid_response_ids = response_ids[:valid_response_length]\n\n            # decode\n            prompt_str = self.tokenizer.decode(valid_prompt_ids, skip_special_tokens=True)\n            response_str = self.tokenizer.decode(valid_response_ids, skip_special_tokens=True)\n            eos_token = self.tokenizer.eos_token\n            if response_str.endswith(eos_token):\n                response_str = response_str[: -len(eos_token)]\n\n            ground_truth = data_item.non_tensor_batch[\"reward_model\"][\"ground_truth\"]\n\n            data_source = data_item.non_tensor_batch[self.reward_fn_key]\n\n            extra_info = data_item.non_tensor_batch.get(\"extra_info\", {})\n\n            rollout_reward_scores = data_item.non_tensor_batch.get(\"reward_scores\", {})\n\n            extra_info[\"rollout_reward_scores\"] = rollout_reward_scores\n\n            result = self.compute_score(\n                data_source=data_source,\n                solution_str=response_str,\n                ground_truth=ground_truth,\n                extra_info=extra_info,\n            )\n\n            score: float\n            if isinstance(result, dict):\n                score = result[\"score\"]\n                # Store the information including original reward\n                for key, value in result.items():\n                    reward_extra_info[key].append(value)\n            else:\n                score = result\n                reward_extra_info[\"acc\"].append(score)\n\n            reward = score\n\n            if self.overlong_buffer_cfg.enable:\n                overlong_buffer_len = self.overlong_buffer_cfg.len\n                expected_len = self.max_resp_len - overlong_buffer_len\n                exceed_len = valid_response_length - expected_len\n                overlong_penalty_factor = self.overlong_buffer_cfg.penalty_factor\n                overlong_reward = min(-exceed_len / overlong_buffer_len * overlong_penalty_factor, 0)\n                reward += overlong_reward\n                if self.overlong_buffer_cfg.log:\n                    reward_extra_info[\"overlong_reward\"].append(overlong_reward)\n                    reward_extra_info[\"overlong\"].append(overlong_reward < 0)\n\n            reward_tensor[i, valid_response_length - 1] = reward\n\n            if data_source not in already_print_data_sources:\n                already_print_data_sources[data_source] = 0\n\n            if already_print_data_sources[data_source] < self.num_examine:\n                already_print_data_sources[data_source] += 1\n                print(\"[prompt]\", prompt_str)\n                print(\"[response]\", response_str)\n                print(\"[ground_truth]\", ground_truth)\n                if isinstance(result, dict):\n                    for key, value in result.items():\n                        print(f\"[{key}]\", value)\n                else:\n                    print(\"[score]\", score)\n\n        if return_dict:\n            return {\n                \"reward_tensor\": reward_tensor,\n                \"reward_extra_info\": reward_extra_info,\n            }\n        else:\n            return reward_tensor\n# Copyright 2024 Bytedance Ltd. and/or its affiliates\n# Copyright 2022 EleutherAI and the HuggingFace Inc. team. All rights reserved.\n# Licensed under the Apache License, Version 2.0 (the \"License\");\n# you may not use this file except in compliance with the License.\n# You may obtain a copy of the License at\n#\n#     http://www.apache.org/licenses/LICENSE-2.0\n#\n# Unless required by applicable law or agreed to in writing, software\n# distributed under the License is distributed on an \"AS IS\" BASIS,\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n# See the License for the specific language governing permissions and\n# limitations under the License.\n# Adapted from https://github.com/EleutherAI/lm-evaluation-harness/blob/main/lm_eval/tasks/hendrycks_math/utils.py\n\nimport math\nimport os\nimport re\nimport signal\nimport threading\n\nimport sympy\nfrom pylatexenc import latex2text\nfrom sympy.parsing import sympy_parser\n\nfrom .prime_math import math_normalize\nfrom .prime_math.grader import math_equal\n\n\nMAX_SYMBOLIC_INPUT_CHARS = 512\n_LATEX_TO_TEXT = latex2text.LatexNodes2Text()\n\n\nclass timeout:\n    def __init__(self, seconds=1, error_mes